public class Main {

    // Single-line comment: minimum passing marks
    static final int PASS_MARKS = 40;

    /*
     * Multi-line comment:
     * This method checks if a student passed.
     * Returns true if marks >= PASS_MARKS.
     */
    static boolean hasPassed(int marks) {
        return marks >= PASS_MARKS;
    }

    public static void main(String[] args) {
        int studentMarks = 75;

        // Check and print result
        System.out.println("Marks  : " + studentMarks);
        System.out.println("Result : " + (hasPassed(studentMarks) ? "PASS" : "FAIL"));
    }
}
